package com.dragonblockarcanedba.client.render.ki;

import com.dragonblockarcanedba.DragonBlockArcaneDBA;
import net.minecraft.resources.Identifier;

/**
 * Canvas textures for the complex effects toolkit (COMPLEX-STANDARD).
 * Generated by tools/gen_complex_assets.py: white intensity images with
 * torn alpha silhouettes, so vertex color carries the theme and the
 * DbaShaders pattern erodes the edges. Sampled through
 * DbaShaders.additiveType(Identifier) or alphaType(Identifier).
 */
public final class ComplexTextures {

    private ComplexTextures() {}

    /** One tall flame tongue: wide base at the bottom of the file, torn tip at the top. */
    public static final Identifier FLAME_TONGUE = DragonBlockArcaneDBA.id("textures/entity/fx/flame_tongue.png");

    /** A horizontal wisp strip: torn ridged edges, streaked core, tapered ends. */
    public static final Identifier TENDRIL = DragonBlockArcaneDBA.id("textures/entity/fx/tendril.png");
}
